<span class="line"><span style="color:#61AFEF;">dotnet-trace</span><span style="color:#98C379;"> collect</span><span style="color:#D19A66;"> -p</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">pi</span><span style="color:#ABB2BF;">d&gt; </span><span style="color:#D19A66;">--providers</span><span style="color:#98C379;"> Microsoft-DotNETCore-SampleProfiler</span></span>
